import { readFileSync } from 'node:fs'

const MODES = ['merge', 'merge2', 'regions']

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function diff(base, side, who) {
  const n = base.length
  const m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const changes = []
  let i = 0
  let j = 0
  let ci = 0
  let cj = 0
  const flush = (ei, ej) => {
    if (ei > ci || ej > cj) changes.push({ bs: ci, be: ei, ss: cj, se: ej, who })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush(i, j)
      i++
      j++
      ci = i
      cj = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  flush(n, m)
  return changes
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) {
    if (l === '%%%') docs.push([])
    else docs[docs.length - 1].push(l)
  }
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs

  const changes = [...diff(base, mine, 0), ...diff(base, theirs, 1)]
  changes.sort((a, b) => a.bs - b.bs || a.who - b.who)

  const out = []
  let conflict = false
  const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])
  let pos = 0
  let k = 0
  const stable = to => {
    if (to > pos) out.push({ kind: 'stable', lines: base.slice(pos, to) })
  }
  while (k < changes.length) {
    const group = [changes[k++]]
    const start = group[0].bs
    let end = group[0].be
    while (k < changes.length && changes[k].bs <= end) {
      end = Math.max(end, changes[k].be)
      group.push(changes[k++])
    }
    stable(start)
    pos = end
    const baseLines = base.slice(start, end)
    let r
    if (group.length === 1) {
      const c = group[0]
      const src = c.who === 0 ? mine : theirs
      r = { kind: c.who === 0 ? 'mine' : 'theirs', lines: src.slice(c.ss, c.se) }
    } else {
      const side = (who, src) => {
        const cs = group.filter(c => c.who === who)
        if (!cs.length) return baseLines
        const first = cs[0]
        const lastBe = Math.max(...cs.map(c => c.be))
        const last = cs.reduce((a, c) => (c.be >= a.be ? c : a))
        return src.slice(first.ss - (first.bs - start), last.se + (end - lastBe))
      }
      const m = side(0, mine)
      const t = side(1, theirs)
      if (same(m, t)) r = { kind: 'both', lines: m }
      else if (same(m, baseLines)) r = { kind: 'theirs', lines: t }
      else if (same(t, baseLines)) r = { kind: 'mine', lines: m }
      else r = { kind: 'conflict', mine: m, base: baseLines, theirs: t }
    }
    if (r.kind === 'conflict') conflict = true
    out.push(r)
  }
  stable(base.length)

  const res = []
  for (const r of out) {
    if (mode === 'regions') {
      if (r.kind === 'conflict') res.push(`conflict mine=${r.mine.length} base=${r.base.length} theirs=${r.theirs.length}`)
      else res.push(`${r.kind} ${r.lines.length}`)
    } else if (r.kind === 'conflict') {
      res.push('<<<<<<< mine', ...r.mine)
      if (mode === 'merge') res.push('||||||| base', ...r.base)
      res.push('=======', ...r.theirs, '>>>>>>> theirs')
    } else res.push(...r.lines)
  }
  process.stdout.write(res.map(l => `${l}\n`).join(''))
  process.exitCode = conflict ? 1 : 0
}

main()
EOF
