{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let names = null
const seen = new Set()
const ballots = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  if (w[0] === 'candidates') {
    if (names !== null || ballots.length) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    names = []
    for (const nm of w.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(nm)) fail(`error: line ${n}: invalid candidate name ${nm}`)
      if (seen.has(nm)) fail(`error: line ${n}: candidate ${nm} is declared twice`)
      seen.add(nm)
      names.push(nm)
    }
  } else if (w[0] === 'ballot') {
    if (names === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(w[1])) fail(`error: line ${n}: count must be a positive integer`)
    const r = new Set()
    for (const nm of w.slice(2)) {
      if (!seen.has(nm)) fail(`error: line ${n}: unknown candidate ${nm}`)
      if (r.has(nm)) fail(`error: line ${n}: candidate ${nm} is repeated`)
      r.add(nm)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}
if (names === null) fail('error: no candidates')

const continuing = new Set(names)
const history = [] // Map per round
const out = []
let winner = null
while (true) {
  const counts = new Map(names.filter((x) => continuing.has(x)).map((x) => [x, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((x) => continuing.has(x))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  history.push(counts)
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  const sorted = [...counts.entries()].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  let line = `round ${history.length}: ` + sorted.map(([k, v]) => `${k}=${v}`).join(' ')
  line += ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const win = sorted.find(([, v]) => v * 2n > active)
  if (win) { winner = win[0]; break }
  let tied = sorted.filter(([, v]) => v === sorted[sorted.length - 1][1]).map(([k]) => k)
  while (tied.length > 1) {
    let reduced = false
    for (const h of history) {
      const vals = tied.map((k) => h.get(k))
      const min = vals.reduce((a, b) => (b < a ? b : a))
      if (vals.some((v) => v !== min)) {
        tied = tied.filter((k) => h.get(k) === min)
        reduced = true
        break
      }
    }
    if (!reduced) break
  }
  const elim = tied.reduce((a, b) => (b > a ? b : a))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${history.length}\n${end}\n`)
EOF
