import { readFileSync } from 'node:fs'

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const end = s.slice(2).search(/[/?#]/)
    const e = end < 0 ? s.length : end + 2
    r.authority = s.slice(2, e)
    s = s.slice(e)
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const rest = a.slice(at + 1)
  const colon = rest.indexOf(':', rest.lastIndexOf(']') + 1)
  return colon >= 0
    ? { userinfo, host: rest.slice(0, colon), port: rest.slice(colon + 1) }
    : { userinfo, host: rest, port: undefined }
}

function removeDots(path) {
  let input = path
  const out = []
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../')) { input = input.slice(3); out.pop() }
    else if (input === '/..') { input = '/'; out.pop() }
    else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out.push(seg)
      input = input.slice(seg.length)
    }
  }
  return out.join('')
}

class Fail extends Error {}

function pct(s, name) {
  if (s === undefined) return s
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new Fail(`the ${name} has a truncated percent-encoding`)
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

function normalize(r) {
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  let path = r.path
  let userinfo, host, port
  const hasAuth = r.authority !== undefined
  if (hasAuth) ({ userinfo, host, port } = splitAuthority(r.authority))
  // checks in order: path, userinfo, host, query, fragment
  path = pct(path, 'path')
  userinfo = pct(userinfo, 'userinfo')
  host = pct(host, 'host')
  const query = pct(r.query, 'query')
  const fragment = pct(r.fragment, 'fragment')
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (hasAuth) {
    host = lower(host)
    if (port === '' || (scheme !== undefined && port === DEFAULT_PORTS[scheme])) port = undefined
    out += '//' + (userinfo !== undefined ? userinfo + '@' : '') + host + (port !== undefined ? ':' + port : '')
  }
  path = removeDots(path)
  if (hasAuth && path === '') path = '/'
  out += path
  if (query !== undefined) out += '?' + query
  if (fragment !== undefined) out += '#' + fragment
  return out
}

function resolve(base, ref) {
  const b = parse(base)
  const r = parse(ref)
  const t = {}
  if (r.scheme !== undefined) {
    Object.assign(t, r, { path: removeDots(r.path) })
  } else if (r.authority !== undefined) {
    Object.assign(t, r, { scheme: b.scheme, path: removeDots(r.path) })
  } else {
    t.scheme = b.scheme
    t.authority = b.authority
    t.fragment = r.fragment
    if (r.path === '') {
      t.path = b.path
      t.query = r.query !== undefined ? r.query : b.query
    } else {
      if (r.path.startsWith('/')) t.path = removeDots(r.path)
      else {
        let merged
        if (b.authority !== undefined && b.path === '') merged = '/' + r.path
        else {
          const i = b.path.lastIndexOf('/')
          merged = i >= 0 ? b.path.slice(0, i + 1) + r.path : r.path
        }
        t.path = removeDots(merged)
      }
      t.query = r.query
    }
  }
  return normalize(t)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  try {
    lines.forEach((line, idx) => {
      const n = idx + 1
      try {
        if (args[0] === 'normalize') out.push(normalize(parse(line)))
        else {
          const sp = line.indexOf(' ')
          if (sp < 0) throw new Fail('expected a base and a reference')
          const base = line.slice(0, sp)
          if (parse(base).scheme === undefined) throw new Fail('the base has no scheme')
          out.push(resolve(base, line.slice(sp + 1)))
        }
      } catch (e) {
        if (e instanceof Fail) throw new Fail(`line ${n}: ${e.message}`)
        throw e
      }
    })
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  process.stdout.write(out.map((l) => l + '\n').join(''))
}

