{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parse } from './parse.js'
import { Sheet } from './eval.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}
const mode = args[0]

const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const line = lines[i].replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') continue
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
  const addr = m[1]
  const content = m[2]
  const am = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(addr)
  if (!am || Number(am[2]) < 1) fail(`line ${i + 1}: invalid cell address ${addr}`)
  const key = addr.toUpperCase()
  if (cells.has(key)) fail(`line ${i + 1}: cell ${key} is declared twice`)
  cells.set(key, content)
}

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function colNum(s) {
  return s.length === 1 ? s.charCodeAt(0) - 64 : (s.charCodeAt(0) - 64) * 26 + s.charCodeAt(1) - 64
}
const keys = [...cells.keys()].map((k) => {
  const m = /^([A-Z]+)(\d+)$/.exec(k)
  return { k, c: colNum(m[1]), r: Number(m[2]) }
})
keys.sort((a, b) => a.c - b.c || a.r - b.r)

const out = []
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const { k } of keys) out.push(`${k}=${sheet.format(sheet.get(k))}`)
} else {
  const sheet = new Sheet(cells)
  for (const { k } of keys) {
    const deps = sheet.deps(k)
    out.push(`${k}:${deps.map((d) => ' ' + d).join('')}`)
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
"}

{"file_path":"src/parse.js","content":"// Formula parser. Returns an AST, or null when the grammar rejects the body.
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^\d+(\.\d+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z]+[0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0].toUpperCase() }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

export function parse(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const bad = () => { throw new Error('grammar') }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { k: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) bad()
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (isOp('(')) {
      p++
      const e = cmp()
      if (!isOp(')')) bad()
      p++
      return e
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++; return { k: 'call', name: t.v, args } }
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          bad()
        }
        return { k: 'call', name: t.v, args }
      }
      if (t.v === 'TRUE') return { k: 'bool', v: true }
      if (t.v === 'FALSE') return { k: 'bool', v: false }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.t !== 'word') bad()
        p++
        return { k: 'range', a: t.v, b: t2.v }
      }
      return { k: 'ref', a: t.v }
    }
    bad()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e.message === 'grammar') return null
    throw e
  }
}
"}

{"file_path":"src/eval.js","content":"import { parse } from './parse.js'

