      l = { k: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { k: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) bad()
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (isOp('(')) {
      p++
      const e = cmp()
      if (!isOp(')')) bad()
      p++
      return e
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++; return { k: 'call', name: t.v, args } }
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          bad()
        }
        return { k: 'call', name: t.v, args }
      }
      if (t.v === 'TRUE') return { k: 'bool', v: true }
      if (t.v === 'FALSE') return { k: 'bool', v: false }
      if (isOp(':')) {
        p++
