if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}
const mode = args[0]

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const line = lines[i].replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') continue
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
  const addr = m[1]
  const am = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(addr)
  if (!am || Number(am[2]) < 1) fail(`line ${i + 1}: invalid cell address ${addr}`)
  const key = addr.toUpperCase()
  if (cells.has(key)) fail(`line ${i + 1}: cell ${key} is declared twice`)
  cells.set(key, m[2])
}

function colNum(s) {
  return s.length === 1 ? s.charCodeAt(0) - 64 : (s.charCodeAt(0) - 64) * 26 + s.charCodeAt(1) - 64
}
const keys = [...cells.keys()].map((k) => {
  const m = /^([A-Z]+)(\d+)$/.exec(k)
  return { k, c: colNum(m[1]), r: Number(m[2]) }
})
keys.sort((a, b) => a.c - b.c || a.r - b.r)

const sheet = new Sheet(cells)
const out = []
for (const { k } of keys) {
  if (mode === 'values') out.push(`${k}=${sheet.format(sheet.get(k))}\n`)
  else out.push(`${k}:${sheet.deps(k).map((d) => ' ' + d).join('')}\n`)
}
process.stdout.write(out.join(''))
"}

