{"file_path":"src/scanner.js","content":"export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  // pos[i] = [line, col] of code point i
  const pos = new Array(n + 1)
  let line = 1
  let col = 1
  for (let i = 0; i < n; i++) {
    pos[i] = [line, col]
    const c = cs[i]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
  }
  pos[n] = [line, col]
  const fail = (i, reason) => {
    throw new ScanError(pos[i][0], pos[i][1], reason)
  }

  const tokens = []
  const push = (i, kind, body) => tokens.push({ line: pos[i][0], col: pos[i][1], kind, body })

  // consume a digit run starting at j (first char is a digit); underscores between digits
  const run = (j, ok) => {
    while (j < n) {
      if (ok(cs[j])) j++
      else if (cs[j] === '_' && ok(cs[j - 1]) && ok(cs[j + 1])) j += 2
      else break
    }
    return j
  }

  let i = 0
  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      i++
      continue
    }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 1
      let j = i + 2
      while (j < n && depth > 0) {
        if (cs[j] === '/' && cs[j + 1] === '*') {
          depth++
          j += 2
        } else if (cs[j] === '*' && cs[j + 1] === '/') {
          depth--
          j += 2
        } else j++
      }
      if (depth > 0) fail(i, 'unterminated block comment')
      i = j
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) fail(i, 'unterminated string')
      push(i, 'rawstring', JSON.stringify(cs.slice(i + 2, j).join('')))
      i = j + 1
      continue
    }
    if (isIdStart(c)) {
      let j = i + 1
      while (j < n && isIdPart(cs[j])) j++
      const w = cs.slice(i, j).join('')
      push(i, KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      i = j
      continue
    }
    if (isDigit(c)) {
      let j = i + 1
      const p = (cs[i + 1] || '').toLowerCase()
      let bad = false
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        const ok = p === 'x' ? isHex : p === 'b' ? isBin : isOct
        j = i + 2
        if (ok(cs[j])) j = run(j, ok)
        else bad = true
      } else {
        j = run(i, isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) j = run(j + 1, isDigit)
        if (cs[j] === 'e' || cs[j] === 'E') {
          let k = j + 1
          if (cs[k] === '+' || cs[k] === '-') k++
          if (isDigit(cs[k])) j = run(k, isDigit)
        }
      }
      if (bad || isIdPart(cs[j])) {
        while (isIdPart(cs[j])) j++
        fail(i, `invalid number ${cs.slice(i, j).join('')}`)
      }
      push(i, 'number', cs.slice(i, j).join(''))
      i = j
      continue
    }
    if (c === '"') {
      let j = i + 1
      let val = ''
      for (;;) {
        if (j >= n) fail(i, 'unterminated string')
        const d = cs[j]
        if (d === '"') break
        if (d === '\n') fail(j, 'newline in string')
        if (d !== '\\') {
          val += d
          j++
          continue
        }
        const e = cs[j + 1]
        if (e === undefined) fail(i, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) {
          val += simple[e]
          j += 2
        } else if (e === 'x') {
          if (!(isHex(cs[j + 2]) && isHex(cs[j + 3]))) fail(j, 'invalid escape \\x')
          val += String.fromCharCode(parseInt(cs[j + 2] + cs[j + 3], 16))
          j += 4
        } else if (e === 'u') {
          if (cs[j + 2] !== '{') fail(j, 'invalid escape \\u')
          let k = j + 3
          while (isHex(cs[k])) k++
          if (k === j + 3 || cs[k] !== '}') fail(j, 'invalid escape \\u')
          const cp = parseInt(cs.slice(j + 3, k).join(''), 16)
          if (cp > 0x10ffff) fail(j, 'invalid escape \\u')
          val += String.fromCodePoint(cp)
          j = k + 1
        } else fail(j, `invalid escape \\${e}`)
      }
      push(i, 'string', JSON.stringify(val))
      i = j + 1
      continue
    }
    const two = c + (cs[i + 1] || '')
    if (PUNCT2.has(two)) {
      push(i, 'punct', two)
      i += 2
      continue
    }
    if (PUNCT1.has(c)) {
      push(i, 'punct', c)
      i++
      continue
    }
    fail(i, `unexpected character ${c}`)
  }
  return tokens
}
"}

