import { readFileSync } from 'node:fs'

const NAME = /^[A-Za-z0-9_.-]+$/
const fail = (msg, code = 2) => {
  process.stderr.write(msg + '\n')
  process.exit(code)
}
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

const args = process.argv.slice(2)
const mode = args[0]
let workers = 0
if (mode === 'waves' || mode === 'explain') {
  if (args.length !== 1) fail('error: usage: cli.js waves|explain|pack <workers>')
} else if (mode === 'pack') {
  if (args.length !== 2) fail('error: usage: cli.js waves|explain|pack <workers>')
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail('error: usage: cli.js waves|explain|pack <workers>')

let input = ''
try { input = readFileSync(0, 'utf8') } catch { input = '' }
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depUses = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) if (!NAME.test(x)) fail(`error: line ${n}: invalid task name ${x}`)
    depUses.push(...w.slice(1))
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const x of depUses) if (!cost.has(x)) fail(`error: unknown task ${x}`)

const names = [...cost.keys()].sort(cmp)
const dl = new Map(names.map((t) => [t, [...(deps.get(t) || [])].sort(cmp)]))

// cycle detection
const color = new Map()
const stack = []
function dfs(t) {
  color.set(t, 1)
  stack.push(t)
  for (const d of dl.get(t)) {
    const c = color.get(d)
    if (c === 1) {
      const cyc = stack.slice(stack.indexOf(d)).concat(d)
      fail('error: cycle: ' + cyc.join(' -> '), 3)
    }
    if (!c) dfs(d)
  }
  stack.pop()
  color.set(t, 2)
}
for (const t of names) if (!color.get(t)) dfs(t)

// topo order via memoized recursion (acyclic)
const start = new Map(), finish = new Map(), depth = new Map()
function calc(t) {
  if (finish.has(t)) return
  let s = 0n, d = 0
  for (const x of dl.get(t)) {
    calc(x)
    if (finish.get(x) > s) s = finish.get(x)
    if (depth.get(x) + 1 > d) d = depth.get(x) + 1
  }
  start.set(t, s); finish.set(t, s + cost.get(t)); depth.set(t, d)
}
for (const t of names) calc(t)
let total = 0n
for (const t of names) if (finish.get(t) > total) total = finish.get(t)

const out = []
if (mode === 'waves') {
  const ws = []
  for (const t of names) (ws[depth.get(t)] ||= []).push(t)
  ws.forEach((g, k) => out.push(`wave ${k}: ${g.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const t of names) out.push(`${t} start=${start.get(t)} finish=${finish.get(t)} depth=${depth.get(t)}`)
  out.push(`total ${total}`)
} else {
  const rev = new Map(names.map((t) => [t, []]))
  for (const t of names) for (const d of dl.get(t)) rev.get(d).push(t)
  const prio = new Map()
  const pr = (t) => {
    if (prio.has(t)) return prio.get(t)
    let m = 0n
    for (const x of rev.get(t)) { const p = pr(x); if (p > m) m = p }
    prio.set(t, m + cost.get(t))
    return m + cost.get(t)
  }
  names.forEach(pr)
  const order = [...names].sort((a, b) => (prio.get(a) > prio.get(b) ? -1 : prio.get(a) < prio.get(b) ? 1 : cmp(a, b)))
  const done = new Map() // finish of started tasks
  const freeAt = new Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let remaining = order.slice()
  let t = 0n
  let makespan = 0n
  while (remaining.length) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      const idx = remaining.findIndex((x) => dl.get(x).every((d) => done.has(d) && done.get(d) <= t))
      if (idx < 0) break
      const x = remaining[idx]
      remaining.splice(idx, 1)
      const f = t + cost.get(x)
      done.set(x, f)
      freeAt[w] = f
      runs[w].push(`${x}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (!remaining.length) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  runs.forEach((r, i) => out.push(`worker ${i}:` + r.map((s) => ' ' + s).join('')))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + '\n')
