export const ADDR = /^([A-Za-z]{1,2})([0-9]{1,3})$/

export function parseAddr(s) {
  const m = ADDR.exec(s)
  if (!m || Number(m[2]) < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
  return { col, row: Number(m[2]), key: L + Number(m[2]) }
}

function fail(msg) {
  const e = new Error(msg)
  e.sheetError = true
  throw e
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const cells = new Map()
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
    const a = parseAddr(m[1])
    if (!a) fail(`line ${i + 1}: invalid cell address ${m[1]}`)
    if (cells.has(a.key)) fail(`line ${i + 1}: cell ${a.key} is declared twice`)
    cells.set(a.key, { ...a, content: m[2] })
  })
  const list = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)
  return { cells, list }
}
