if (lines.length && lines[lines.length - 1] === '') lines.pop()

let names = null
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (names !== null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const nm of t.slice(1)) {
      if (!NAME.test(nm)) fail(`error: line ${n}: invalid candidate name ${nm}`)
      if (seen.has(nm)) fail(`error: line ${n}: candidate ${nm} is declared twice`)
      seen.add(nm)
    }
    names = t.slice(1)
  } else if (t[0] === 'ballot') {
    if (names === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const nm of t.slice(2)) {
      if (!names.includes(nm)) fail(`error: line ${n}: unknown candidate ${nm}`)
      if (seen.has(nm)) fail(`error: line ${n}: candidate ${nm} is repeated`)
      seen.add(nm)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
}
if (names === null) fail('error: no candidates')

const cont = new Set(names)
const history = [] // Map per round
const out = []
let winner = null
for (let k = 1; ; k++) {
  const counts = new Map([...cont].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => cont.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  history.push(counts)
  let total = 0n
  for (const b of ballots) total += b.count
  const list = [...cont].sort((a, b) => (counts.get(a) > counts.get(b) ? -1 : counts.get(a) < counts.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
  let line = `round ${k}: ${list.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const w = list.find((c) => counts.get(c) * 2n > active)
  if (w !== undefined) { winner = w; break }
  let min = null
  for (const c of cont) if (min === null || counts.get(c) < min) min = counts.get(c)
  let tied = [...cont].filter((c) => counts.get(c) === min)
  while (tied.length > 1) {
    let changed = false
    for (const h of history) {
      const vals = tied.map((c) => h.get(c))
      let lo = vals[0]
      let same = true
      for (const v of vals) { if (v !== vals[0]) same = false; if (v < lo) lo = v }
      if (!same) { tied = tied.filter((c) => h.get(c) === lo); changed = true; break }
    }
    if (!changed) break
  }
  const elim = tied.sort()[tied.length - 1]
  cont.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner !== null ? `winner ${winner}` : 'no winner'
if (mode === 'rounds') process.stdout.write(out.filter(Boolean).join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${history.length}\n${end}\n`)
EOF
