export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

export function splitAuthority(a) {
  let userinfo
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const from = a.lastIndexOf(']') + 1
  const c = a.indexOf(':', from)
  if (c < 0) return { userinfo, host: a, port: undefined }
  return { userinfo, host: a.slice(0, c), port: a.slice(c + 1) }
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
export function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const ch = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(ch) ? ch : '%' + h.toUpperCase()
  })
}

const truncated = (s) => /%(?![0-9A-Fa-f]{2})/.test(s)

export function removeDots(path) {
  let inp = path
  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(out.lastIndexOf('/'), 0))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }
const lowerHost = (h) => h.replace(/%[0-9A-F]{2}|[A-Z]/g, (x) => (x[0] === '%' ? x : x.toLowerCase()))

// Returns the normalized string, or throws Error with the component name.
export function normalize(u) {
  const parts = {}
  if (u.authority !== undefined) Object.assign(parts, splitAuthority(u.authority))
  const checks = [['path', u.path], ['userinfo', parts.userinfo], ['host', parts.host], ['query', u.query], ['fragment', u.fragment]]
  for (const [name, v] of checks) if (v !== undefined && truncated(v)) throw new Error(name)
  const scheme = u.scheme === undefined ? undefined : u.scheme.replace(/[A-Z]/g, (c) => c.toLowerCase())
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  let path = pct(u.path)
  if (u.authority !== undefined) {
    let port = parts.port === undefined ? '' : pct(parts.port)
    if (port === DEFAULT_PORT[scheme]) port = ''
    out += '//'
    if (parts.userinfo !== undefined) out += pct(parts.userinfo) + '@'
    out += lowerHost(pct(parts.host))
    if (port !== '') out += ':' + port
  }
  path = removeDots(path)
  if (u.authority !== undefined && path === '') path = '/'
  out += path
  if (u.query !== undefined) out += '?' + pct(u.query)
  if (u.fragment !== undefined) out += '#' + pct(u.fragment)
  return out
}

export function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.authority !== undefined) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    t.fragment = ref.fragment
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      t.query = ref.query
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
    }
  }
  return t
}
