        if (fin.has(u)) continue
        if (!dl.get(u).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best === null || prio.get(u) > prio.get(best)) best = u
      }
      if (best === null) break
      const f = t + cost.get(best)
      fin.set(best, f)
      freeAt[wi] = f
      runs[wi].push(`${best}@${t}-${f}`)
      if (f > makespan) makespan = f
      done++
    }
    if (done >= names.length) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    for (const f of fin.values()) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  runs.forEach((r, i) => out.push(`worker ${i}:` + r.map((x) => ' ' + x).join('')))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + '\n')
