import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

function diff(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const changes = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) changes.push({ bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return changes
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) fail('error: usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) {
    if (l === '%%%') docs.push([])
    else docs[docs.length - 1].push(l)
  }
  if (docs.length !== 3) fail('error: expected three parts separated by %%%')
  const [mine, base, theirs] = docs
  const all = [
    ...diff(base, mine).map(c => ({ ...c, side: 0 })),
    ...diff(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)

  const out = []
  let conflict = false
  const stable = (from, to) => {
    if (to > from) {
      if (mode === 'regions') out.push(`stable ${to - from}`)
      else out.push(...base.slice(from, to))
    }
  }
  let pos = 0, k = 0
  while (k < all.length) {
    const group = [all[k++]]
    const r0 = group[0].bs
    let r1 = group[0].be
    while (k < all.length && all[k].bs <= r1) {
      r1 = Math.max(r1, all[k].be)
      group.push(all[k++])
    }
    stable(pos, r0)
    pos = r1
    const sideLines = (s, doc) => {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) return base.slice(r0, r1)
      const minB = Math.min(...cs.map(c => c.bs)), maxB = Math.max(...cs.map(c => c.be))
      const minS = Math.min(...cs.map(c => c.ss)), maxS = Math.max(...cs.map(c => c.se))
      return doc.slice(minS - (minB - r0), maxS + (r1 - maxB))
    }
    const b = base.slice(r0, r1)
    let label, res
    if (group.length === 1) {
      const c = group[0]
      label = c.side === 0 ? 'mine' : 'theirs'
      res = (c.side === 0 ? mine : theirs).slice(c.ss, c.se)
    } else {
      const m = sideLines(0, mine), t = sideLines(1, theirs)
      if (eq(m, t)) { label = 'both'; res = m }
      else if (eq(m, b)) { label = 'theirs'; res = t }
      else if (eq(t, b)) { label = 'mine'; res = m }
      else {
        conflict = true
        if (mode === 'regions') out.push(`conflict mine=${m.length} base=${b.length} theirs=${t.length}`)
        else {
          out.push('<<<<<<< mine', ...m)
          if (mode === 'merge') out.push('||||||| base', ...b)
          out.push('=======', ...t, '>>>>>>> theirs')
        }
        continue
      }
    }
    if (mode === 'regions') out.push(`${label} ${res.length}`)
    else out.push(...res)
  }
  stable(pos, base.length)
  if (out.length) process.stdout.write(out.join('\n') + '\n')
  process.exitCode = conflict ? 1 : 0
}

main()
