import { readFileSync } from 'node:fs'

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'replay' && mode[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function num(value, field, least) {
  if (!UINT.test(value) || BigInt(value) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(value)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    const at = (msg) => new Fail(`line ${i + 1}: ${msg}`)
    try {
      const d = f[0]
      if (d === 'bucket' || d === 'window' || d === 'route' || d === 'event') {
        if (d !== 'event' && events.length) throw new Fail('declarations must come before the first event')
      }
      if (d === 'bucket') {
        if (f.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const capacity = num(f[2], 'capacity', 1)
        const refill = num(f[3], 'refill', 0)
        const per = num(f[4], 'per', 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'bucket', capacity, refill, per })
      } else if (d === 'window') {
        if (f.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const limit = num(f[2], 'limit', 0)
        const span = num(f[3], 'span', 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'window', limit, span })
      } else if (d === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        const list = []
        for (const p of f.slice(2)) {
          if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
          list.push(policies.get(p))
        }
        routes.set(f[1], list)
      } else if (d === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = num(f[1], 'tick', 0)
        if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: f[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw at(e.message)
      throw e
    }
  }
  return { routes, events }
}

function run({ routes, events }) {
  const states = new Map()
  const stateOf = (p, key) => {
    let m = states.get(p)
    if (!m) states.set(p, (m = new Map()))
    let s = m.get(key)
    if (!s) {
      s = p.kind === 'bucket' ? { num: p.capacity * p.per, last: null } : { ticks: [] }
      m.set(key, s)
    }
    return s
  }
  const prefixes = [...routes.keys()]
  const results = []
  for (const { tick, key } of events) {
    let best = null
    for (const p of prefixes) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
    if (best === null) { results.push({ tick, key, deny: null }); continue }
    const list = routes.get(best)
    const sts = list.map((p) => stateOf(p, key))
    list.forEach((p, i) => {
      const s = sts[i]
      if (p.kind === 'bucket') {
        if (s.last !== null) {
          s.num += p.refill * (tick - s.last)
          const max = p.capacity * p.per
          if (s.num > max) s.num = max
        }
        s.last = tick
      } else {
        const cut = tick - p.span
        s.ticks = s.ticks.filter((t) => t > cut)
      }
    })
    let deny = null
    for (let i = 0; i < list.length && deny === null; i++) {
      const p = list[i], s = sts[i]
      const ok = p.kind === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit
      if (!ok) deny = p.name
    }
    if (deny === null) {
      list.forEach((p, i) => {
        if (p.kind === 'bucket') sts[i].num -= p.per
        else sts[i].ticks.push(tick)
      })
    }
    results.push({ tick, key, deny })
  }
  return results
}

let out = ''
try {
  const results = run(parse(readFileSync(0, 'utf8')))
  if (mode[0] === 'replay') {
    for (const r of results) out += `${r.tick} ${r.key} ${r.deny === null ? 'allow' : 'deny ' + r.deny}\n`
  } else {
    const per = new Map()
    let a = 0, d = 0
    for (const r of results) {
      const c = per.get(r.key) || { a: 0, d: 0 }
      if (r.deny === null) { c.a++; a++ } else { c.d++; d++ }
      per.set(r.key, c)
    }
    for (const k of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      out += `${k} allowed=${per.get(k).a} denied=${per.get(k).d}\n`
    }
    out += `total allowed=${a} denied=${d}\n`
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
